ops.template:
// Generated by the Bugsee wizard. Injects debug ids into the built JavaScript and uploads its source maps.
// Usage: node scripts/bugsee-sourcemaps.mjs [outputDir]
// Output directory: the argument, else $BUGSEE_SOURCEMAPS_DIR, else tsconfig.json "outDir", else ./dist.
// The app token comes from BUGSEE_APP_TOKEN, or from .env.bugsee-build-plugin (never committed).
// This runs inside your build, so a missing token or a default directory that was not built is a
// warning and a skip, never a failed build. A failing upload does fail it.
import { spawnSync } from 'node:child_process';
import { existsSync, readdirSync, readFileSync, statSync } from 'node:fs';
import { dirname, join, relative, resolve } from 'node:path';

function readJson(file) {
  try {
    return JSON.parse(
      readFileSync(file, 'utf8')
        .replace(/^\uFEFF/, '')
        .replace(/("(?:\\.|[^"\\])*")|\/\/[^\n]*|\/\*[\s\S]*?\*\//g, (m, str) => str || '')
        .replace(/,(\s*[}\]])/g, '$1'),
    );
  } catch {
    return {};
  }
}

// a leading "-" is a build flag npm/pnpm appended after the chained script, not a directory
const arg = process.argv[2]?.startsWith('-') ? undefined : process.argv[2];
const explicit = arg || process.env.BUGSEE_SOURCEMAPS_DIR;

// tsconfig "outDir", following relative "extends" (as a path relative to this project)
function findOutDir(file, seen = new Set()) {
  const abs = resolve(file);
  if (seen.has(abs) || seen.size > 8) return undefined;
  seen.add(abs);
  const cfg = readJson(abs);
  if (typeof cfg.compilerOptions?.outDir === 'string') {
    return relative(process.cwd(), resolve(dirname(abs), cfg.compilerOptions.outDir)) || undefined;
  }
  if (typeof cfg.extends !== 'string' || !cfg.extends.startsWith('.')) return undefined;
  const base = resolve(dirname(abs), cfg.extends);
  return findOutDir(existsSync(base) && statSync(base).isFile() ? base : `${base}.json`, seen);
}
const outDir = findOutDir('tsconfig.json');

// the newest file time under a directory (a directory's own time does not move when files in it
// are overwritten, which is how a rebuild usually happens); bounded, 0 for an empty directory
function newest(dir) {
  let latest = 0;
  let budget = 5000;
  const stack = [dir];
  while (stack.length > 0 && budget > 0) {
    const d = stack.pop();
    let entries;
    try {
      entries = readdirSync(d, { withFileTypes: true });
    } catch {
      continue;
    }
    for (const e of entries) {
      if (--budget < 0) break;
      const f = join(d, e.name);
      if (e.isDirectory()) {
        if (e.name !== 'node_modules') stack.push(f);
        continue;
      }
      try {
        latest = Math.max(latest, statSync(f).mtimeMs);
      } catch {
        // a dangling or looping symlink, or an unreadable file: not a reason to fail the build
      }
    }
  }
  return latest;
}
// without an explicit directory: of tsconfig "outDir" and ./dist, the one that exists, the freshest
// if both do (an Angular tsconfig names ./dist/out-tsc, which its builder never writes: the app lands
// in dist/<app>; an old toolchain may have left a stale directory behind)
const defaults = [...new Set([...(outDir ? [outDir] : []), 'dist'])];
const built = defaults.filter((d) => existsSync(d));
const out = explicit || built.sort((a, b) => newest(b) - newest(a))[0] || defaults[0];
if (!existsSync(out)) {
  if (explicit) {
    console.error(`bugsee: output directory "${out}" not found. Build first, or pass the right directory.`);
    process.exit(1);
  }
  const tried = defaults.map((d) => `"${d}"`).join(' or ');
  console.warn(`bugsee: output directory ${tried} not found. Skipping the source map upload; pass the directory as an argument or set BUGSEE_SOURCEMAPS_DIR.`);
  process.exit(0);
}

const envFile = '.env.bugsee-build-plugin';
if (!process.env.BUGSEE_APP_TOKEN && existsSync(envFile)) {
  for (const line of readFileSync(envFile, 'utf8').split(/\r?\n/)) {
    const m = /^\s*(?:export\s+)?BUGSEE_APP_TOKEN\s*=\s*(.*?)\s*$/.exec(line);
    if (!m) continue;
    const v = m[1];
    const dq = /^"((?:\\.|[^"\\])*)"(?:\s+#.*)?$/.exec(v);
    const sq = /^'([^']*)'(?:\s+#.*)?$/.exec(v);
    if (dq) process.env.BUGSEE_APP_TOKEN = dq[1].replace(/\\(["\\])/g, '$1');
    else if (sq) process.env.BUGSEE_APP_TOKEN = sq[1];
    else process.env.BUGSEE_APP_TOKEN = v.replace(/^#.*$|\s+#.*$/, ''); // an inline comment needs a space before the #
    break; // the first line wins, as the wizard reads it
  }
}
if (!process.env.BUGSEE_APP_TOKEN) {
  console.warn('bugsee: BUGSEE_APP_TOKEN is not set (environment or .env.bugsee-build-plugin). Skipping the source map upload.');
  process.exit(0);
}

const version = process.env.BUGSEE_APP_VERSION || readJson('package.json').version || '0.0.0';
const git = spawnSync('git', ['rev-list', '--count', 'HEAD'], { encoding: 'utf8' });
const build =
  process.env.BUGSEE_BUILD || process.env.GITHUB_RUN_NUMBER || process.env.BUILD_NUMBER ||
  (git.status === 0 ? git.stdout.trim() : '') || '1';

function run(args) {
  const r = spawnSync('npx', ['--no-install', 'bugsee-cli', ...args], { stdio: 'inherit', shell: process.platform === 'win32' });
  if (r.error) {
    console.error(`bugsee: could not run bugsee-cli: ${r.error.message}`);
    process.exit(1);
  }
  if (r.status !== 0) process.exit(r.status ?? 1);
}

run(['sourcemaps', 'inject', out]);
run(['debug-files', 'upload', out, '--type', 'sourcemaps', '--version', version, '--build', build]);
